private void initPlayer() {
    GLFisheyeView gLFisheyeView;
    this.mPanoPlayer = new HSMediaPlayer(getApplicationContext(), false);
    this.mStreamType = GlobalDefines.isPanoramicDevice(this.mLoginHandle) ? 1 : 0;
    LogUtil.i(TAG, "<literal omitted>" + this.mStreamType);
    int i = this.mCameraMode;
    if (i == 1) {
        gLFisheyeView = new GLFisheyeView(this, 1, 2);
        gLFisheyeView.setPositionON(0, true);
        gLFisheyeView.setPositionON(1, true);
        gLFisheyeView.setDisplayMode(2);
        gLFisheyeView.setMode(14);
        gLFisheyeView.setSubViewType(0);
    } else if (i == 3) {
        gLFisheyeView = new GLFisheyeView(this, 2, 2);
        gLFisheyeView.setPositionON(0, true);
        gLFisheyeView.setPositionON(1, true);
        gLFisheyeView.setPositionON(2, true);
        gLFisheyeView.setDisplayMode(3);
        gLFisheyeView.setMode(17);
        LoginHandle loginHandle = this.mLoginHandle;
        if (loginHandle != null && loginHandle.getVideoSplicing() == 7) {
            gLFisheyeView.setSubViewType(19);
        } else {
            gLFisheyeView.setSubViewType(10);
        }
        gLFisheyeView.setStretch(true);
    } else {
        gLFisheyeView = new GLFisheyeView(this);
        if (GlobalDefines.isPanoramicDevice(this.mLoginHandle)) {
            gLFisheyeView.setDisplayMode(5);
            this.mPlayMode = 0;
        }
        gLFisheyeView.setMode(this.mPlayMode);
    }
    gLFisheyeView.setOnTouchListener(this);
    this.mPanoPlayer.setGlFishView(gLFisheyeView);
    ((ActivityConfigSelectAlarmAreaBinding) this.binding).flSelectAlarmAreaPlayerContainer.addView(this.mPanoPlayer.getGLFisheyeView());
    this.mPanoPlayer.GetHandler(this.mBaseActivityHandler);
    this.mPanoPlayer.setHWDecodeStatus(false, false);
    HSMediaLibrary.SetContext(this.mPanoPlayer, null, null, null);
    Player.SelectWindow(0);
